def price(base, voorraad_pct):
    pts = [(0,10), (50,1), (80,0.4), (100,0.1)]
    p = max(0, min(100, voorraad_pct))
    for (x0,y0),(x1,y1) in zip(pts, pts[1:]):
        if x0 <= p <= x1:
            t = (p-x0)/(x1-x0) if x1!=x0 else 0
            return base * (y0 + t*(y1-y0))
    return base
